WFJ.Data.add("gossip", {
  ["34010f3c6a9cea3b"] = { "I Fanglord sono morti! Non tutto è perduto!\n\nIl rituale del risveglio, però, è piuttosto complesso. Non lo si può compiere da soli.\n\nMi occuperò io di tutti i preparativi necessari, ma ho bisogno che tu mi protegga. Gli incubi evocati dal viaggio di Naralex attraverso il ⟦Emerald Dream=Sogno di Smeraldo⟧ si dimostrano piuttosto temibili. Senza il tuo aiuto, questa missione è destinata a fallire.\n\nQuando sarai <pronto/pronta> a difendermi, dimmelo, e ti farò strada fino alla camera di Naralex.", "." },
  ["3401e97ab1efa1a7"] = { "Maywiki, non ho più la mia ⟦Zandalar Haruspex's Belt=Cintura dell'Aruspice degli Zandalari⟧. Puoi aiutarmi?", "." },
  ["3402e6ccd35a8a4f"] = { "Il mio Gizmotic Almanacotron dice che dovremmo battere i goblin di venti secondi in più rispetto all'ultima volta!", "." },
  ["34059b9403754895"] = { "Ha! Non hai la stoffa... per ora! Torna da me dopo aver imparato qualcosa!", "." },
  ["34063272f2f755bf"] = { "Prima o poi parlerai. Tanto vale che lo sputi fuori adesso.", "." },
  ["340bc2bd88f1f7fc"] = { "Interessante... Questo è più di quanto mi aspettassi. Delizioso...", "." },
  ["340db6000240ec6d"] = { "Stregoni, eh. Beh, non l'hai sentito da me, ma girano voci che quel genere di gente si riunisca in un bar chiamato Slaughtered Lamb, nel ⟦Mage Quarter=Quartiere dei Maghi⟧.", "." },
  ["3414fac82d57fdc9"] = { "Non ho commesso errori.", "." },
  ["341bcd322cb1c2ae"] = { "Grazie per aver liberato me, mio fratello e tutti voi! Ora possiamo finalmente riposare in pace.", "." },
  ["341c7a80e679a1e5"] = { "L'hai visto? C'è uno del Flagello laggiù!", "." },
  ["341e75d0e62a0e63"] = { "La casa d'aste", "." },
  ["34211904b49c1e32"] = { "Fatti avanti! Prendi qui le tue ali piccanti bollenti!", "." },
  ["34211e322dab4d53"] = { "Andrà tutto bene, Awbee. I tuoi aggressori sono stati eliminati.", "." },
  ["3425da563fcb33b7"] = { "La risata di %s si spegne...", "." },
  ["34309a001085cfe3"] = { "Leggerò le parole incise sulla pietra, e tu devi trovare un modo per accenderla.", "." },
  ["3434132e025ab68f"] = { "Chi osa interferire con i Sons of Arugal?", "." },
  ["34392e088a20b537"] = { "Mangia questo, figlia mia. Ti aiuterà a sentirti meglio.", "." },
  ["34480b3ff3fce9bb"] = { "Il Dun Baldar North Bunker protegge l'ingresso orientale di Dun Baldar.\n\nNon è controllato da nessuna delle due parti.", "." },
  ["344c960bb713b210"] = { "Voglio vedere la Torre dei Maghi.", "." },
  ["344f58a29e31d1ea"] = { "Ti ricordi quando Danath radunò tutti i mercenari di ⟦Stormwind=Roccavento⟧ e marciammo a combattere a ⟦Nethergarde=Guardiafatua⟧?", "." },
  ["34511cbb35947a7f"] = { "Se pensi di avere la forza di battere il buon metallo per farne armi e armature per l'⟦Horde=Orda⟧, cerca Dwukk accanto alla forgia ardente nell'angolo nord-ovest di ⟦Razor Hill=Tranciacolle⟧.", "." },
  ["3453250b67e1fb6f"] = { "Vuoi pescare? Allora ti serviranno gli attrezzi giusti.", "." },
  ["345a0be31d7728f7"] = { "Le mie forze scemano, mortale. Ho fatto ciò che avevo promesso, la via è libera. Ora faccio ritorno al luogo da cui provengo.", "." },
  ["346a238eddc1a559"] = { "Ti servono provviste?", "." },
  ["347195942cde9fee"] = { "Le tue abilità nel preparare pozioni superano le mie. Cerca il non morto dottor Herbert Halsey nell'Apothecarium di ⟦Undercity=Sepulcra⟧. Ha l'abilità per addestrarti ancora, e potrai vedere con i tuoi occhi la triste condizione del suo popolo.", "." },
  ["3471ddfe212a61e8"] = { "La Counting House di ⟦Stormwind=Roccavento⟧ si trova vicino ai cancelli principali nel ⟦Trade District=Quartiere del Commercio⟧ di ⟦Stormwind=Roccavento⟧. E quando ti stancherai di contare i tuoi soldi, passa al Gilded Rose a bere qualcosa.", "." },
  ["34788062cd4e426e"] = { "Il ⟦Snowfall Graveyard=Cimitero di Nevealta⟧ appartiene all'⟦Alliance=Alleanza⟧.", "." },
  ["348036368c3ab7ce"] = { "Ti do il benvenuto alla Fiera, giovane! Abbiamo raccolto meraviglie da tutto il mondo, perché tu possa ammirarle. Ah, e per favore fammi sapere se riesci a raccogliere una serie delle carte di Lunacupa minori, perché il padrone... cioè, a me interesserebbero moltissimo.", "." },
  ["3481b5cc37605013"] = { "Ingegneria", "." },
  ["3483e9df30c7269c"] = { "Che tu sia <maledetto/maledetta>, {name}! Un giorno avrò la mia vendetta!", "." },
  ["348abd152831b459"] = { "Guardati da Marduk! Guardatene, o la tua forza avvizzirà.", "." },
  ["348bceab96b23bce"] = { "Sì, sì, ti addestrerò. Non c'è bisogno di alzare la voce.", "." },
  ["348cac1321773086"] = { "%s ruggisce ancora contro Terenthis, ma stavolta il druido sembra capire l'orso.", "." },
  ["348e61dcf82a51e2"] = { "Non vedo l'ora di scoprire cosa farà questo campione d'acqua!", "." },
  ["349493af709e4355"] = { "Ti prego, salvami!", "." },
  ["349c78777b9ab1e1"] = { "È giunto il momento, fratelli. Non dobbiamo permettere al nemico di avanzare attraverso il ⟦Frost Dagger Pass=Passo di Lama del Gelo⟧. Alcuni di noi periranno di certo, ma qualcuno di voi si sottrarrebbe a questo dovere? A questo onore? Avanti! Per l'⟦Horde=Orda⟧!", "." },
  ["34ad0837c7446169"] = { "OK Fengus, dove sei?! Vieni a darmi dell'amico degli gnoll mentre io ti do 'na martellata in testa!", "." },
  ["34ae7ced898f2662"] = { "%s emette un ruggito profondo, allertando gli alleati vicini e andando su tutte le furie!", "." },
  ["34b5b6f60425e928"] = { "Lysta, evoca... l'abominio!", "." },
  ["34bb5550702f7f71"] = { "Come posso aiutarti, amico?", "." },
  ["34c3c622d667b01a"] = { "Dov'è l'anziano Riversong?", "." },
  ["34c43ab65c5391b9"] = { "È tutto raccolto, {class}. Tutto viene trasportato a ⟦Silithus=Silitus⟧ per i preparativi finali e dovrebbe arrivare entro un giorno. Tutte le nostre forze unite attendono l'<eroe/eroina> che completerà la riunificazione dello Scettro delle Sabbie Mutevoli, suonerà il gong e darà inizio alla Guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧.", "." },
  ["34c60ac7e6f31b82"] = { "Spero proprio che restino vivi abbastanza a lungo perché io possa... presentarmi.", "." },
  ["34c81a80380e08aa"] = { "<Minuscolo/Minuscola> {class}! Non sei all'altezza del clan ⟦Blackrock=Roccianera⟧!", "." },
  ["34cb5dbb2a9dced0"] = { "Aiuuuuuuuuuuuuuuuuuuuuuuutooooooooooooo!!!", "." },
  ["34d3726877f49085"] = { "SMOTTS! EHI, SMOTTS!! VIENI FUORI A GIOCARE!", "." },
  ["34e6098a931984f4"] = { "Grazie ancora, {name}. Questa terra rara sarà molto utile nei miei esperimenti.", "." },
  ["34edce95c2c6d0c3"] = { "Non troverai scuoiatori qui fuori a Dun Morogh, <ragazzo/ragazza>: si trovano per lo più a ⟦Ironforge=Forgiardente⟧, se vuoi farti addestrare.", "." },
  ["34ef1aeee683ae5e"] = { "È un onore per me rifornire gli avventurieri, perché sono eroi in divenire.", "." },
  ["34f2c4b86ab1444d"] = { "Il ⟦Frostwolf Graveyard=Cimitero dei Lupi Bianchi⟧ si trova lungo il bordo della strada, poco a nord del ⟦Frostwolf Village=Villaggio dei Lupi Bianchi⟧.\n\nAl momento è controllato dall'⟦Alliance=Alleanza⟧.", "." },
  ["34f6192db660371e"] = { "Va bene, sacchi d'ossa da quattro soldi. Vediamo cosa sapete fare. Colpite l'avversario e non fermatevi finché non lo dico io.", "." },
  ["34f7f9667fb1c192"] = { "Qui a ⟦Moonglade=Radaluna⟧ sanno come organizzare una festa. Chi l'avrebbe mai detto?", "." },
  ["34f94fe620958064"] = { "Portami alla ⟦Northpass Tower=Torre Passo Nord⟧.", "." },
